// pl.yaml rule pl.dates def DATE_WEEKDAY_BEFORE
export const DATE_WEEKDAY_BEFORE =
  /(?<![\p{L}])(?<w>poniedział\p{L}*|wtor\p{L}*|środ\p{L}*|czwart\p{L}*|piąt\p{L}*|sobot\p{L}*|niedziel\p{L}*|pon\.?|pn\.?|wt\.?|śr\.?|czw\.?|pt\.?|sob\.?|niedz\.?|nd\.?)[ \t ]*,?[ \t ]*$/iu;

